-- ============================================================================
-- V9 - Technical Master editable catalog (ONEMEP-29): per-category sections
--      and fields. Supersedes the V8 flat field table.
--
-- The catalog is fully dynamic: heads (tm_section) and fields (tm_field) can be
-- created / toggled active / deleted per category via the API. A project sheet =
-- the ACTIVE fields of its category (series_code); values in
-- project_technical_field_value. Seeded from the official PTMS Field Dictionary.
-- ============================================================================

DROP TABLE IF EXISTS project_technical_field_value;
DROP TABLE IF EXISTS tm_field_category;
DROP TABLE IF EXISTS tm_field;
DROP TABLE IF EXISTS tm_section;

CREATE TABLE tm_section (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    series_code   INT          NOT NULL,
    title         VARCHAR(120) NOT NULL,
    section_order INT          NOT NULL,
    active        BOOLEAN      NOT NULL DEFAULT TRUE
);
CREATE INDEX idx_tm_section_series ON tm_section (series_code);

CREATE TABLE tm_field (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    section_id    BIGINT       NOT NULL,
    series_code   INT          NOT NULL,
    label         VARCHAR(200) NOT NULL,
    field_key     VARCHAR(160) NOT NULL,
    unit          VARCHAR(60),
    data_type     VARCHAR(10)  NOT NULL,
    required      BOOLEAN      NOT NULL DEFAULT FALSE,
    feeds         VARCHAR(10)  NOT NULL DEFAULT 'REF',
    notes         VARCHAR(300),
    field_order   INT          NOT NULL,
    active        BOOLEAN      NOT NULL DEFAULT TRUE,
    CONSTRAINT fk_tm_field_section FOREIGN KEY (section_id) REFERENCES tm_section (id),
    CONSTRAINT uq_tm_field_key UNIQUE (series_code, field_key),
    CONSTRAINT ck_tm_field_dtype CHECK (data_type IN ('NUMBER','TEXT')),
    CONSTRAINT ck_tm_field_feeds CHECK (feeds IN ('YES','REF'))
);
CREATE INDEX idx_tm_field_section ON tm_field (section_id);
CREATE INDEX idx_tm_field_series ON tm_field (series_code);

CREATE TABLE project_technical_field_value (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    technical_master_id BIGINT       NOT NULL,
    field_key           VARCHAR(160) NOT NULL,
    value               VARCHAR(2000),
    created_date        TIMESTAMP    NOT NULL,
    created_by          BIGINT,
    updated_by          BIGINT,
    updated_date        TIMESTAMP,
    CONSTRAINT fk_tm_value_master FOREIGN KEY (technical_master_id) REFERENCES project_technical_master (id),
    CONSTRAINT uq_tm_value UNIQUE (technical_master_id, field_key)
);
CREATE INDEX idx_tm_value_master ON project_technical_field_value (technical_master_id);

-- ── Sections (heads) per category ──

-- ── Fields per section ──

-- Realign IDENTITY sequences so service-created sections/fields continue after the seed.
SELECT setval(pg_get_serial_sequence('tm_section', 'id'), (SELECT COALESCE(MAX(id), 1) FROM tm_section));
SELECT setval(pg_get_serial_sequence('tm_field', 'id'), (SELECT COALESCE(MAX(id), 1) FROM tm_field));
